async function boot(){const parsed=new DOMParser().parseFromString(await(await fetch('index.html')).text(),'text/html');for(const n of [...parsed.body.children])if(n.tagName!=='SCRIPT')document.body.append(n);await import('./app.js');await until(()=>window.openPlay?.state.decks[0].track,'App');app=window.openPlay;app.engine.init();app.engine.audioMonitor.mutePhysical(true);$('#music-status').textContent='Import the private research MP3 using Import audio below';readiness=setInterval(()=>{if(app.state.tracks.some(t=>t.file?.name==='SDRNR-private-research-159.mp3')){$('#music-run').disabled=false;$('#music-status').textContent='Imported file available; ready';}},250);}
